# Writes the archery range's hedra command files (every model but the hero target) and the drawn
# meadow texture. Run from models/env: /usr/bin/python3 make_env.py. Hedra is up Z, front -Y (the
# GLB comes out Y up, front +Z); colours are exact Island Joy 16 hexes, so the bake snaps with error 0.
import math
import os

from PIL import Image

HEX = {"white": "ffffff", "mint": "6df7c1", "teal": "11adc1", "slate": "606c81", "night": "393457",
       "pine": "1e8875", "green": "5bb361", "lime": "a1e55a", "yellow": "f7e476", "orange": "f99252",
       "rose": "cb4d68", "plum": "6a3771", "crimson": "c92464", "pink": "f48cb6", "peach": "f7b69e",
       "khaki": "9b9c82"}


def rgb(name):
    h = HEX[name]
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def col(name):
    return "--base-color " + " ".join(f"{c / 255:.4f}" for c in rgb(name))


def beam(name, a, b, w, d=None, mat=None):
    """a box of cross-section w x d from point a to point b (hedra coords)"""
    d = d or w
    dx, dy, dz = (b[i] - a[i] for i in range(3))
    L = math.sqrt(dx * dx + dy * dy + dz * dz)
    c = [(a[i] + b[i]) / 2 for i in range(3)]
    ux, uy, uz = dx / L, dy / L, dz / L
    ta = math.degrees(math.acos(max(-1, min(1, uz))))
    tb = math.degrees(math.atan2(ux, -uy)) if abs(ta) > 1e-6 else 0.0
    out = [f"add mesh cube --name {name} --size 1 --location {c[0]:.4f} {c[1]:.4f} {c[2]:.4f}",
           f"scale {w} {d} {L:.4f}", "apply --scale", f"set rotation {ta:.3f} 0 {tb:.3f}"]
    if mat:
        out.append(f"material assign {mat}")
    return out


def write(name, lines):
    with open(name + ".txt", "w") as f:
        f.write("\n".join(lines) + "\n")


# ---------------------------------------------------------------- the meadow
# Renderer coords: x -9.5..9.5, z -14..5 (hedra y = -z: -5..14). One slab, its top textured from above
# with a drawn 95 x 95 texture (0.2 m a texel, ~2 splats at 0.1 m): grass on two steps, light
# patches, yellow and pink flowers, white and peach clover; the shooting line and the archer's mat.
TW, TH = 95, 95
X0, Z0 = -9.5, -14.0          # texel (0, 0) is the far left corner (renderer x, z)


def texel(x, z):
    return int((x - X0) / 0.2), int((z - Z0) / 0.2)


def draw_meadow(path):
    import random
    rnd = random.Random(7)
    im = Image.new("RGB", (TW, TH), rgb("green"))
    px = im.load()
    # light patches: blobs of lime
    for _ in range(46):
        cx, cy, r = rnd.randrange(TW), rnd.randrange(TH), rnd.uniform(1.5, 4.0)
        for y in range(int(cy - r) - 1, int(cy + r) + 2):
            for x in range(int(cx - r * 1.4) - 1, int(cx + r * 1.4) + 2):
                if 0 <= x < TW and 0 <= y < TH and ((x - cx) / 1.4) ** 2 + (y - cy) ** 2 <= r * r:
                    px[x, y] = rgb("lime")
    # flowers: 2 x 2 texel dots (a single texel is under two splats)
    for _ in range(70):
        x, y = rnd.randrange(TW - 1), rnd.randrange(TH - 1)
        c = rgb(rnd.choice(["yellow", "yellow", "pink", "white"]))
        for dx in (0, 1):
            for dy in (0, 1):
                px[x + dx, y + dy] = c
    # the shooting line (white, 0.4 m) at z 0.9 and the archer's straw mat round (0, 2.2)
    _, ly = texel(0, 0.8)
    for x in range(TW):
        for y in (ly, ly + 1):
            px[x, y] = rgb("white")
    mx, my = texel(0, 2.2)
    for y in range(my - 4, my + 5):
        for x in range(mx - 5, mx + 6):
            px[x, y] = rgb("khaki")
    im.save(path)


os.makedirs("textures", exist_ok=True)
draw_meadow("textures/meadow.png")
write("ground", [
    "# The meadow: a 19 x 19 m slab, its top textured from above (textures/meadow.png, drawn by",
    "# make_env.py). Only the top is kept: the camera never sees the sides. Generated by make_env.py.",
    "new",
    f"material new Meadow --base-color 1 1 1 --no-slot",
    "add mesh cube --name Ground --size 1 --location 0 4.5 -0.3",
    "scale 19 19 0.6",
    "apply --scale",
    "active Ground",
    "mode edit",
    'select face where "normal.z < 0.9"',
    "delete only-faces",
    'select face where "normal.z > 0.9"',
    "material assign Meadow",
    "uv project-from-view top --scale-to-bounds",
    "mode object",
    "material texture Meadow base-color textures/meadow.png",
    "select all",
    "shade flat",
    "export ground.glb",
])

