# ---------------------------------------------------------------- the archer (one game bone)
# 1.75 m, facing -Y (the meadow), seen mostly from behind: a teal tunic, slate legs, plum boots, a
# crimson hood, a quiver of crimson-fletched arrows on the back. The bow arm (left, -X) reaches
# forward; the draw arm (right) bends back to the cheek. Origin at the feet.
A = ["# The archer: blocky, seen from behind; the bow (bow.txt) and the arrows are separate bones.",
     "# Generated by make_env.py.",
     "new",
     f"material new Tunic {col('teal')} --no-slot",
     f"material new Legs {col('slate')} --no-slot",
     f"material new Boots {col('plum')} --no-slot",
     f"material new Skin {col('peach')} --no-slot",
     f"material new Hood {col('crimson')} --no-slot",
     f"material new Belt {col('khaki')} --no-slot",
     f"material new Quiver {col('orange')} --no-slot",
     f"material new Fletch {col('white')} --no-slot"]
for s, x in (("L", -0.13), ("R", 0.13)):
    A += [f"add mesh cube --name Leg{s} --size 1 --location {x} 0 0.42", "scale 0.2 0.22 0.68", "apply --scale",
          "material assign Legs",
          f"add mesh cube --name Boot{s} --size 1 --location {x} -0.04 0.1", "scale 0.24 0.32 0.2", "apply --scale",
          "material assign Boots"]
A += ["add mesh cube --name Tunic --size 1 --location 0 0 1.06", "scale 0.56 0.34 0.62", "apply --scale",
      "material assign Tunic",
      "add mesh cube --name Skirt --size 1 --location 0 0 0.72", "scale 0.6 0.38 0.16", "apply --scale",
      "material assign Tunic",
      "add mesh cube --name Belt --size 1 --location 0 0 0.84", "scale 0.6 0.38 0.1", "apply --scale",
      "material assign Belt",
      "add mesh ico-sphere --name Head --subdivisions 1 --radius 0.19 --location 0 -0.02 1.55",
      "material assign Skin",
      "add mesh cone --name Hood --vertices 6 --radius1 0.24 --radius2 0.02 --depth 0.42 --location 0 0.06 1.68 --rotation -18 0 0",
      "material assign Hood",
      "add mesh cube --name Cape --size 1 --location 0 0.16 1.3", "scale 0.5 0.06 0.26", "apply --scale",
      "material assign Hood"]
# arms: left (bow) arm straight forward at shoulder height, right arm bent: upper arm out, forearm in
A += beam("ArmL", (-0.3, 0.0, 1.3), (-0.34, -0.62, 1.32), 0.13, mat="Tunic")
A += beam("HandL", (-0.34, -0.62, 1.32), (-0.34, -0.72, 1.32), 0.13, mat="Skin")
A += beam("ArmR", (0.3, 0.0, 1.3), (0.42, 0.1, 1.38), 0.13, mat="Tunic")
A += beam("ForeR", (0.42, 0.1, 1.38), (0.12, -0.12, 1.44), 0.12, mat="Tunic")
# the quiver on the back, tilted, with three fletchings out of its top
A += beam("Quiver", (0.12, 0.22, 0.92), (0.26, 0.26, 1.5), 0.17, mat="Quiver")
for i, (dx, dz) in enumerate(((0.0, 0.0), (0.07, -0.03), (-0.06, -0.02))):
    A += beam(f"Fl{i}", (0.26 + dx, 0.26, 1.48 + dz), (0.29 + dx, 0.27, 1.66 + dz), 0.09, mat="Fletch")
A += ["select all", "shade flat", "export archer.glb"]
write("archer", A)

# ---------------------------------------------------------------- the bow (a game bone at the grip)
# A longbow 1.4 m tall in the Y-Z plane, bellied forward (-Y). Origin at the grip: the game cants it
# and bends it (a scale along Y, the depth) as the draw comes back.
B = ["# The bow: four rose-wood limbs bellied forward and a plum grip (no string: at the texel it is a",
     "# hair, and seen from behind it hid the limbs); origin at the grip.",
     "# Generated by make_env.py.",
     "new",
     f"material new Wood {col('rose')} --no-slot",
     f"material new Grip {col('plum')} --no-slot",
     ]
pts = [(0, 0.22, 0.7), (0, 0.02, 0.42), (0, -0.06, 0.0), (0, 0.02, -0.42), (0, 0.22, -0.7)]
for i in range(4):
    B += beam(f"Limb{i}", pts[i], pts[i + 1], 0.13, mat="Wood")
B += beam("Grip", (0, -0.06, 0.16), (0, -0.06, -0.16), 0.13, mat="Grip")
B += ["select all", "shade flat", "export bow.glb"]
write("bow", B)

